"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { toast } from "sonner";
import { usePlayback, effectiveDuration } from "@/lib/playback-store";
import { durationToSeconds } from "@/lib/walls";
import { getVoice } from "@/lib/voices";
import { cn } from "@/lib/utils";
import { PostToSocials } from "./PostToSocials";

/**
 * Beveled phone display with REAL audio playback.
 *
 * The phone screen now plays the spoken-lyrics MP3 generated by Z.ai's TTS
 * engine (see /api/audio). A real <audio> element is owned by this component
 * and bound to the store via:
 *  - audioRef.current.src ← track.audioUrl
 *  - ontimeupdate → store.onTimeUpdate
 *  - onloadedmetadata → store.onLoadedMetadata
 *  - onended → store.onEnded
 *  - onerror → store.onError
 *
 * If the audio URL isn't ready yet (TTS still generating in the background),
 * we poll /api/audio?episodeId=...&voice=... every 2s until it returns a
 * URL, then load it into the element and auto-start playback.
 *
 * Lyric captions now sync to the actual audio position via ontimeupdate —
 * no more fake 1s ticker.
 */
interface PhoneVideo {
  id: string;
  status: string;
  pageUrl: string;
  posterUrl: string;
  frames?: string[];
  mp4Url: string;
  /** Our own copy of the MP4 — outlives P&R's ~24h render link. */
  localMp4?: string;
  audioUrl: string;
  /** YouTube upload state: "" | publishing | published | failed */
  ytStatus?: string;
  ytUrl?: string;
  ytCaptions?: boolean;
  ytError?: string;
}

export function PhoneDisplay({ episodeId }: { episodeId?: string }) {
  const track = usePlayback((s) => s.track);
  const isPlaying = usePlayback((s) => s.isPlaying);
  const positionSec = usePlayback((s) => s.positionSec);
  const durationSec = usePlayback((s) => s.durationSec);
  const playEntire = usePlayback((s) => s.playEntireClip);
  const volume = usePlayback((s) => s.volume);
  const audioLoading = usePlayback((s) => s.audioLoading);
  const audioError = usePlayback((s) => s.audioError);
  const activeWallId = usePlayback((s) => s.activeWallId);
  const toggle = usePlayback((s) => s.toggle);
  const restart = usePlayback((s) => s.restart);
  const seek = usePlayback((s) => s.seek);
  const setPlayEntire = usePlayback((s) => s.setPlayEntireClip);
  const setVolume = usePlayback((s) => s.setVolume);
  const onTimeUpdate = usePlayback((s) => s.onTimeUpdate);
  const onLoadedMetadata = usePlayback((s) => s.onLoadedMetadata);
  const onEnded = usePlayback((s) => s.onEnded);
  const onError = usePlayback((s) => s.onError);
  const setAudioLoading = usePlayback((s) => s.setAudioLoading);
  const setAudioUrl = usePlayback((s) => s.setAudioUrl);
  const isPlayingRef = usePlayback((s) => s.isPlaying);
  const playEntireRef = usePlayback((s) => s.playEntireClip);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const videoRef = useRef<HTMLVideoElement | null>(null);

  // === The episode's P&R video (shown on the phone) ===
  // Stored with its episode so a stale video never shows on the next song.
  const [videoState, setVideoState] = useState<{
    episodeId: string;
    video: PhoneVideo | null;
  } | null>(null);
  const [courseUrl, setCourseUrl] = useState("");
  const [dismissedFor, setDismissedFor] = useState<string | null>(null);

  // === In-phone Joe TV ===
  // The P&R pack is a page, not a file, and its CSP forbids embedding. So the
  // phone plays the pack's 9:16 frames over the song audio itself — no
  // navigating away. Rendering the MP4 upgrades this to the real video.
  const [tvOpen, setTvOpen] = useState(false);
  const [tvPlaying, setTvPlaying] = useState(false);
  const [tvProgress, setTvProgress] = useState(0);
  const [tvFrame, setTvFrame] = useState(0);
  /** How long each pack frame holds the screen. */
  const frameSeconds = 10;
  const [tvError, setTvError] = useState<string | null>(null);
  /**
   * The episode's own song MP3, found even when no wall track is loaded — the
   * phone is often opened straight from the output panel.
   *
   * The pack's `video.audioUrl` points at P&R's anonymous host, whose files are
   * deleted after ~24h, so it is only ever a last resort.
   */
  const [episodeAudio, setEpisodeAudio] = useState<{
    episodeId: string;
    url: string;
  } | null>(null);
  const [mp4Busy, setMp4Busy] = useState(false);
  const [ytBusy, setYtBusy] = useState(false);
  const previewAudioRef = useRef<HTMLAudioElement | null>(null);

  // A track loaded from the wall wins; otherwise show the episode in the
  // output panel, so a freshly made video appears on the phone right away.
  const videoEpisodeId = track?.episodeId ?? episodeId ?? null;

  useEffect(() => {
    if (!videoEpisodeId) return;
    let cancelled = false;
    const load = async () => {
      try {
        const res = await fetch(
          `/api/video?episodeId=${encodeURIComponent(videoEpisodeId)}`,
          { cache: "no-store" }
        );
        if (!res.ok) return;
        const j = await res.json();
        if (cancelled) return;
        setVideoState({
          episodeId: videoEpisodeId,
          video: (j.video as PhoneVideo | null) ?? null,
        });
        if (j.courseUrl) setCourseUrl(j.courseUrl);
      } catch {
        // Offline or no video yet — the song view stays.
      }
    };
    load();
    const interval = setInterval(load, 8000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [videoEpisodeId]);

  const video =
    videoState && videoState.episodeId === videoEpisodeId
      ? videoState.video
      : null;
  const frames = useMemo(() => {
    if (!video) return [];
    if (video.frames?.length) return video.frames;
    return video.posterUrl ? [video.posterUrl] : [];
  }, [video]);
  const hasVideo = Boolean(video && (video.mp4Url || video.posterUrl));
  // Dismissal is per episode, so a new song always starts on the video.
  const showVideo =
    hasVideo && dismissedFor !== videoEpisodeId;

  // Fresh episode → the TV starts closed on the poster.
  useEffect(() => {
    setTvOpen(false);
    setTvPlaying(false);
    setTvProgress(0);
    setTvFrame(0);
    setTvError(null);
  }, [videoEpisodeId]);

  // Resolve same-origin audio for the episode on screen, whatever voice it was
  // rendered in. Runs even before the TV opens so the first tap starts sound.
  useEffect(() => {
    if (!videoEpisodeId) {
      setEpisodeAudio(null);
      return;
    }
    let cancelled = false;
    const load = async () => {
      try {
        const res = await fetch(
          `/api/audio/${encodeURIComponent(videoEpisodeId)}`,
          { cache: "no-store" }
        );
        if (!res.ok) return;
        const j = (await res.json()) as {
          tracks?: { audioUrl?: string | null }[];
        };
        const url = (j.tracks ?? [])
          .map((t) => t.audioUrl)
          .filter((u): u is string => Boolean(u))
          .pop();
        if (cancelled) return;
        setEpisodeAudio(url ? { episodeId: videoEpisodeId, url } : null);
      } catch {
        // Offline — the P&R link is still there as a fallback.
      }
    };
    load();
    const interval = setInterval(load, 8000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [videoEpisodeId]);

  // Same-origin first, P&R last (it expires).
  const tvAudioUrl =
    track?.audioUrl ||
    (episodeAudio && episodeAudio.episodeId === videoEpisodeId
      ? episodeAudio.url
      : null) ||
    video?.audioUrl ||
    null;
  const tvUsingExpiringAudio =
    Boolean(tvAudioUrl) && tvAudioUrl === video?.audioUrl && !track?.audioUrl;

  const startTv = useCallback(() => {
    if (!video) return;
    setTvOpen(true);
    setTvError(null);
    setTvProgress(0);
    setTvFrame(0);
    // The phone's song player and Joe TV must never sing over each other.
    const playback = usePlayback.getState();
    if (playback.isPlaying) playback.pause();
  }, [video]);

  const toggleTv = useCallback(() => {
    const audio = previewAudioRef.current;
    if (!audio) return;
    if (audio.paused) {
      audio.play().catch(() => setTvError("Tap ▶ to start the sound."));
    } else {
      audio.pause();
      setTvPlaying(false);
    }
  }, []);

  // Autoplay is allowed here because opening the TV is a user gesture.
  useEffect(() => {
    if (!tvOpen || video?.mp4Url) return;
    const audio = previewAudioRef.current;
    if (!audio) return;
    audio
      .play()
      .then(() => setTvPlaying(true))
      .catch(() => setTvError("Tap ▶ to start the sound."));
  }, [tvOpen, video?.mp4Url, tvAudioUrl]);

  // While the real MP4 renders, poll the job (free) and swap it in.
  useEffect(() => {
    if (video?.status !== "mp4_rendering" || !videoEpisodeId) return;
    let cancelled = false;
    const poll = async () => {
      try {
        const res = await fetch(`/api/video?jobId=${encodeURIComponent(video.id)}`, {
          cache: "no-store",
        });
        if (!res.ok) return;
        const j = await res.json();
        if (cancelled || !j.video) return;
        setVideoState({ episodeId: videoEpisodeId, video: j.video as PhoneVideo });
        if (j.video.mp4Url) toast.success("Joe's video is ready.");
      } catch {
        // Provider hiccup — the next tick retries.
      }
    };
    const interval = setInterval(poll, 8000);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [video?.status, video?.id, videoEpisodeId]);

  const renderMp4 = useCallback(async () => {
    if (!video || mp4Busy || !videoEpisodeId) return;
    setMp4Busy(true);
    setTvError(null);
    try {
      const res = await fetch("/api/video/mp4", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ jobId: video.id }),
      });
      const j = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(j.error || "MP4 render failed.");
      if (j.video) {
        setVideoState({ episodeId: videoEpisodeId, video: j.video as PhoneVideo });
      }
      if (j.video?.mp4Url) toast.success("MP4 ready — playing in the phone.");
      else if (j.video?.error) setTvError(j.video.error);
      else toast.message("Rendering the MP4 — the phone will switch over when it lands.");
    } catch (e) {
      const msg = e instanceof Error ? e.message : "MP4 render failed.";
      setTvError(msg);
      toast.error(msg);
    } finally {
      setMp4Busy(false);
    }
  }, [video, mp4Busy, videoEpisodeId]);

  /**
   * Upload the finished MP4 to YouTube (description, tags and an SRT caption
   * track built from the pack page). P&R has no YouTube tool, so this goes
   * straight to the channel connected in Backend settings.
   */
  const publishYt = useCallback(async () => {
    if (!video || ytBusy || !videoEpisodeId) return;
    setYtBusy(true);
    try {
      const res = await fetch("/api/youtube/publish", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ jobId: video.id }),
      });
      const j = await res.json().catch(() => ({}));
      if (!res.ok) throw new Error(j.error || "YouTube upload failed.");

      // Re-read the job so the phone shows the live link.
      const fresh = await fetch(
        `/api/video?episodeId=${encodeURIComponent(videoEpisodeId)}`,
        { cache: "no-store" }
      )
        .then((r) => r.json())
        .catch(() => null);
      if (fresh?.video) {
        setVideoState({ episodeId: videoEpisodeId, video: fresh.video as PhoneVideo });
      }
      toast.success(
        j.result?.captions
          ? "On YouTube with captions."
          : "On YouTube.",
        { description: j.result?.url }
      );
      if (j.result && !j.result.captions && j.result.captionNote) {
        toast.message("No caption track", { description: j.result.captionNote });
      }
    } catch (e) {
      const msg = e instanceof Error ? e.message : "YouTube upload failed.";
      toast.error(msg);
    } finally {
      setYtBusy(false);
    }
  }, [video, ytBusy, videoEpisodeId]);

  // === Wire the <audio> element to the store. ===
  // Whenever the track changes, load the new src.
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio || !track) return;
    if (track.audioUrl) {
      // Only set src if it's actually different — setting the same src
      // restarts the audio, which we don't want.
      if (!audio.src.endsWith(track.audioUrl)) {
        audio.src = track.audioUrl;
        audio.load();
      }
    } else {
      // No audio URL yet — start polling.
      audio.src = "";
    }
  }, [track?.audioUrl, track?.episodeId]);

  // === Apply play / pause to the audio element. ===
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio || !track || !track.audioUrl) return;
    if (isPlaying && audio.paused) {
      audio.play().catch((e) => {
        console.error("Audio play() failed:", e);
        onError(e instanceof Error ? e.message : "Playback failed.");
      });
    } else if (!isPlaying && !audio.paused) {
      audio.pause();
    }
  }, [isPlaying, track?.audioUrl, track?.episodeId, onError, track]);

  // === Apply volume. ===
  useEffect(() => {
    const audio = audioRef.current;
    if (audio) audio.volume = Math.max(0, Math.min(1, volume / 100));
  }, [volume]);

  // === Apply seek when positionSec changes externally (e.g. via progress bar). ===
  // We track the last seek we applied to avoid loops with ontimeupdate.
  const lastSeekRef = useRef(-1);
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio || !track || !track.audioUrl) return;
    const diff = Math.abs(audio.currentTime - positionSec);
    if (diff > 1.5) {
      audio.currentTime = positionSec;
    }
    lastSeekRef.current = positionSec;
  }, [positionSec, track?.audioUrl, track]);

  // === Poll for audio URL while we wait for TTS to finish. ===
  useEffect(() => {
    if (!track || track.audioUrl) return;
    if (!audioLoading) setAudioLoading(true);
    let cancelled = false;
    const poll = async () => {
      try {
        const url = `/api/audio?episodeId=${encodeURIComponent(
          track.episodeId
        )}&voice=${encodeURIComponent(track.voice)}`;
        const res = await fetch(url, { cache: "no-store" });
        if (!res.ok) return;
        const j = await res.json();
        if (cancelled) return;
        if (j.hasAudio && j.audioUrl) {
          setAudioUrl(j.audioUrl, j.durationSec || 0);
        }
      } catch (e) {
        console.error("Audio poll failed:", e);
      }
    };
    poll();
    const interval = setInterval(poll, 2500);
    return () => {
      cancelled = true;
      clearInterval(interval);
    };
  }, [track?.episodeId, track?.audioUrl, track?.voice, audioLoading, setAudioLoading, setAudioUrl, track]);

  // === Parse lyrics into a flat list of lines for caption scrolling. ===
  const lyricsText = track?.lyrics ?? "";
  const lyricLines = useMemo(() => {
    if (!lyricsText) return [];
    const lines: { text: string; tag?: string }[] = [];
    let currentTag: string | undefined;
    for (const raw of lyricsText.split(/\r?\n/)) {
      const trimmed = raw.trim();
      const m = trimmed.match(/^\[([A-Z][A-Z0-9 ]*?)\]$/i);
      if (m) {
        currentTag = m[1].toUpperCase();
        continue;
      }
      if (!trimmed) continue;
      lines.push({ text: trimmed, tag: currentTag });
    }
    return lines;
  }, [lyricsText]);

  // === Pick the "current" lyric line based on actual audio position. ===
  const currentLineIdx = useMemo(() => {
    if (!track || lyricLines.length === 0) return -1;
    const dur = effectiveDuration(track, playEntire);
    if (dur <= 0) return 0;
    const ratio = positionSec / dur;
    const idx = Math.min(
      lyricLines.length - 1,
      Math.floor(ratio * lyricLines.length)
    );
    return idx;
  }, [track, playEntire, positionSec, lyricLines]);

  const brandColor = track?.brandColor || "#722F37";
  const durSec = track ? effectiveDuration(track, playEntire) : 0;
  const progressPct = durSec > 0 ? Math.min(100, (positionSec / durSec) * 100) : 0;
  const fmtTime = (s: number) =>
    `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, "0")}`;
  const voiceDef = getVoice(track?.voice);

  // True if we should show the "audio still generating" overlay.
  const showGeneratingOverlay =
    track && audioLoading && !audioError;
  const showErrorOverlay = track && audioError && !audioLoading;

  return (
    <div className="flex flex-col items-center gap-3">
      <div className="relative mx-auto" style={{ width: 280, height: 580 }}>
        {/* Hidden audio element — driven by the effects above. */}
        <audio
          ref={audioRef}
          preload="auto"
          onTimeUpdate={(e) => {
            const a = e.currentTarget;
            onTimeUpdate(a.currentTime, a.duration || 0);
          }}
          onLoadedMetadata={(e) => onLoadedMetadata(e.currentTarget.duration || 0)}
          onEnded={() => onEnded()}
          onError={(e) => {
            // The DOM error event doesn't expose the message cleanly.
            const code = e.currentTarget.error?.code;
            const msg =
              code === 1
                ? "Loading aborted."
                : code === 2
                ? "Network error while loading audio."
                : code === 3
                ? "Audio decode failed."
                : code === 4
                ? "Audio source not supported."
                : "Unknown audio error.";
            onError(msg);
          }}
        />

        {/* === BEVELED PHONE FRAME === */}
        <div
          className="absolute inset-0 rounded-[3rem]"
          style={{
            background:
              "linear-gradient(145deg, oklch(0.78 0.02 60) 0%, oklch(0.32 0.02 50) 35%, oklch(0.22 0.02 50) 50%, oklch(0.42 0.02 60) 65%, oklch(0.78 0.02 60) 100%)",
            boxShadow:
              "0 24px 48px -12px oklch(0.2 0.04 30 / 0.45), 0 0 0 1.5px oklch(0.18 0.02 40), inset 0 2px 4px oklch(0.95 0.01 80 / 0.6), inset 0 -2px 4px oklch(0.12 0.02 40)",
          }}
        />
        <div
          className="absolute inset-[3px] rounded-[2.85rem]"
          style={{
            background:
              "linear-gradient(145deg, oklch(0.16 0.01 40) 0%, oklch(0.08 0.01 40) 50%, oklch(0.16 0.01 40) 100%)",
            boxShadow: "inset 0 0 8px oklch(0 0 0 / 0.6)",
          }}
        />
        <div
          className="absolute inset-[10px] rounded-[2.4rem] overflow-hidden flex flex-col"
          style={{
            background: oklchBgFromBrand(brandColor),
          }}
        >
          {/* === STATUS BAR === */}
          <div className="relative z-10 flex items-center justify-between px-5 pt-3 pb-1 text-[0.65rem] font-medium text-white/90">
            <span className="font-mono">
              {fmtTime(positionSec)} / {fmtTime(durSec || durSec || (track ? durationToSeconds(track.episodeDuration) : 0))}
            </span>
            <div className="absolute left-1/2 -translate-x-1/2 top-2 h-5 w-20 rounded-full bg-black/85" />
            <div className="flex items-center gap-1">
              <SignalDots />
              <BatteryIcon />
            </div>
          </div>

          {/* === MUSIC VIDEO STAGE === */}
          <div className="relative flex-1 mx-2 mt-1 mb-2 rounded-2xl overflow-hidden">
            <Visualizer isPlaying={isPlaying} brandColor={brandColor} />

            {/* Episode title overlay */}
            <div className="absolute inset-x-0 top-0 p-3 bg-gradient-to-b from-black/55 to-transparent">
              <p className="text-[0.55rem] uppercase tracking-wider text-white/70 font-semibold">
                {track?.emoji || "🎙️"} · {track?.wallName || "Now Playing"}
              </p>
              <p className="text-white font-serif text-sm leading-tight font-semibold mt-0.5 line-clamp-2 drop-shadow">
                {track?.episodeTitle || "Load a track from the wall"}
              </p>
              {track && (
                <p className="text-[0.55rem] text-white/60 mt-0.5">
                  Voice: {voiceDef.label}
                </p>
              )}
            </div>

            {/* Generating overlay */}
            {showGeneratingOverlay && (
              <div className="absolute inset-0 flex flex-col items-center justify-center gap-2 bg-black/40 backdrop-blur-sm">
                <div className="h-9 w-9 rounded-full border-2 border-white/40 border-t-white animate-spin" />
                <p className="text-white text-[0.7rem] font-semibold uppercase tracking-wider">
                  Joe is warming up…
                </p>
                <p className="text-white/60 text-[0.6rem]">
                  TTS generating · voice: {voiceDef.label}
                </p>
              </div>
            )}

            {/* Error overlay */}
            {showErrorOverlay && (
              <div className="absolute inset-0 flex flex-col items-center justify-center gap-1 bg-black/60 backdrop-blur-sm p-4 text-center">
                <p className="text-red-300 text-[0.7rem] font-semibold">
                  Audio failed
                </p>
                <p className="text-white/70 text-[0.6rem] leading-snug">
                  {audioError}
                </p>
                <button
                  onClick={() => {
                    // Force a re-poll.
                    const t = track;
                    if (!t) return;
                    setAudioLoading(true);
                    usePlayback.setState({ audioError: null });
                  }}
                  className="mt-2 text-[0.65rem] font-semibold text-white/90 underline"
                >
                  Retry
                </button>
              </div>
            )}

            {/* Center play overlay (only when paused, audio ready, not at end) */}
            {!isPlaying && track && track.audioUrl && !showGeneratingOverlay && !showErrorOverlay && (
              <button
                onClick={toggle}
                className="absolute inset-0 flex items-center justify-center group"
                aria-label="Play"
              >
                <span
                  className="flex items-center justify-center h-14 w-14 rounded-full backdrop-blur-md border-2 border-white/50 transition-transform group-hover:scale-105"
                  style={{ background: "oklch(0 0 0 / 0.35)" }}
                >
                  <PlayIcon className="h-6 w-6 text-white ml-0.5" />
                </span>
              </button>
            )}

            {/* Replay overlay (when at end) */}
            {track && track.audioUrl && positionSec >= durSec && durSec > 0 && !showGeneratingOverlay && !showErrorOverlay && (
              <button
                onClick={restart}
                className="absolute inset-0 flex flex-col items-center justify-center gap-1.5 group"
                aria-label="Replay"
              >
                <span
                  className="flex items-center justify-center h-14 w-14 rounded-full backdrop-blur-md border-2 border-white/50 transition-transform group-hover:scale-105"
                  style={{ background: "oklch(0 0 0 / 0.35)" }}
                >
                  <ReplayIcon className="h-6 w-6 text-white" />
                </span>
                <span className="text-[0.6rem] font-semibold text-white/90 uppercase tracking-wider drop-shadow">
                  Tap to Replay
                </span>
              </button>
            )}

            {/* === LYRIC CAPTIONS === */}
            <div className="absolute inset-x-0 bottom-0 p-3 bg-gradient-to-t from-black/85 via-black/40 to-transparent">
              {track ? (
                <>
                  {lyricLines[currentLineIdx]?.tag && (
                    <p className="text-[0.55rem] uppercase tracking-wider text-white/60 font-semibold mb-1">
                      {lyricLines[currentLineIdx].tag}
                    </p>
                  )}
                  <p
                    key={currentLineIdx}
                    className="text-white text-[0.78rem] leading-snug font-medium drop-shadow text-center line-clamp-2 animate-[fadein_0.4s_ease-out]"
                  >
                    {lyricLines[currentLineIdx]?.text || "♪"}
                  </p>
                  {lyricLines[currentLineIdx + 1] && (
                    <p className="text-white/45 text-[0.7rem] leading-snug mt-1 text-center line-clamp-1">
                      {lyricLines[currentLineIdx + 1].text}
                    </p>
                  )}
                </>
              ) : (
                <div className="text-center py-2">
                  <p className="text-white/70 text-[0.7rem] font-medium">
                    Pick a track from the wall →
                  </p>
                  <p className="text-white/40 text-[0.6rem] mt-0.5">
                    Generate a song, then send it to a wall.
                  </p>
                </div>
              )}
            </div>

            {/* === JOE'S VIDEO LAYER === */}
            {video && video.status === "rendering" && !hasVideo && (
              <div className="absolute bottom-2 left-2 z-20 flex items-center gap-1.5 rounded-full bg-black/70 px-2 py-1 backdrop-blur-sm">
                <span className="h-1.5 w-1.5 rounded-full bg-red-400 animate-pulse" />
                <span className="text-[0.55rem] font-semibold uppercase tracking-wider text-white/90">
                  Filming Joe
                </span>
              </div>
            )}

            {hasVideo && showVideo && video && (
              <div className="absolute inset-0 z-20 bg-black">
                {video.mp4Url ? (
                  <>
                    <video
                      ref={videoRef}
                      src={video.localMp4 || video.mp4Url}
                      poster={video.posterUrl || undefined}
                      autoPlay
                      controls
                      playsInline
                      preload="auto"
                      className="absolute inset-0 h-full w-full object-contain bg-black"
                      onPlay={() => {
                        const s = usePlayback.getState();
                        if (s.isPlaying) s.pause();
                      }}
                    />
                    <div className="absolute right-2 top-2 z-30 flex items-center gap-1.5">
                      <PostToSocials mp4Url={video.mp4Url} title={track?.episodeTitle || "Jobless Joe"} episodeId={videoEpisodeId ?? undefined} variant="pill" />
                      {video.ytUrl ? (
                        <a
                          href={video.ytUrl}
                          target="_blank"
                          rel="noopener noreferrer"
                          title={
                            video.ytCaptions
                              ? "Published to YouTube with captions"
                              : video.ytError || "Published to YouTube"
                          }
                          className="rounded-full bg-black/70 px-2 py-0.5 text-[0.5rem] font-semibold uppercase tracking-wider text-white/90 backdrop-blur-sm hover:bg-black/85"
                        >
                          YouTube ✓
                        </a>
                      ) : (
                        <button
                          onClick={publishYt}
                          disabled={ytBusy}
                          title={video.ytError || "Upload to the connected YouTube channel"}
                          className="rounded-full bg-black/70 px-2 py-0.5 text-[0.5rem] font-semibold uppercase tracking-wider text-white/90 backdrop-blur-sm hover:bg-black/85 disabled:opacity-60"
                        >
                          {ytBusy ? "Publishing…" : "YouTube ↑"}
                        </button>
                      )}
                    </div>
                  </>
                ) : tvOpen ? (
                  <div className="absolute inset-0">
                    {/* object-contain, not cover: the pack bakes its captions into
                        the 9:16 frame, and the phone's stage is a shallower box, so
                        cover crops ~9% off the top and bottom — i.e. the words. */}
                    {frames.map((src, i) => (
                      <img
                        key={`${src}-${i}`}
                        src={src}
                        alt="Joe TV frame"
                        className={`absolute inset-0 h-full w-full object-contain transition-opacity duration-700 ${
                          i === tvFrame ? "opacity-100" : "opacity-0"
                        }`}
                      />
                    ))}
                    {frames.length === 0 && (
                      <div className="absolute inset-0 flex items-center justify-center px-6 text-center">
                        <p className="text-white/70 text-[0.7rem]">
                          Joe&apos;s take is still being written.
                        </p>
                      </div>
                    )}
                    <audio
                      ref={previewAudioRef}
                      // Our own copy first: the P&R audio link is an anonymous
                      // host that expires, and this one is same-origin.
                      src={tvAudioUrl || undefined}
                      preload="auto"
                      onPlaying={() => setTvPlaying(true)}
                      onPause={() => setTvPlaying(false)}
                      onEnded={() => {
                        setTvPlaying(false);
                        setTvProgress(1);
                      }}
                      onError={() =>
                        setTvError(
                          tvUsingExpiringAudio
                            ? "The P&R audio link expired — open the full page."
                            : "The song audio wouldn't load — open the full page."
                        )
                      }
                      onTimeUpdate={(e) => {
                        const a = e.currentTarget;
                        const d = a.duration || 0;
                        if (!d) return;
                        setTvProgress(a.currentTime / d);
                        if (frames.length > 1) {
                          // Pace the frames by time, not by fraction of the song:
                          // spreading 4 creatives across 90 seconds left each on
                          // screen for 22s, which reads as a frozen image.
                          setTvFrame(
                            Math.floor(a.currentTime / frameSeconds) % frames.length
                          );
                        }
                      }}
                    />
                    {!tvPlaying && frames.length > 0 && (
                      <button
                        onClick={toggleTv}
                        className="absolute inset-0 flex items-center justify-center group"
                        aria-label="Play Joe's video"
                      >
                        <span className="flex h-14 w-14 items-center justify-center rounded-full border-2 border-white/60 bg-black/40 backdrop-blur-md transition-transform group-hover:scale-105">
                          <PlayIcon className="h-6 w-6 text-white ml-0.5" />
                        </span>
                      </button>
                    )}
                    <div className="absolute inset-x-0 bottom-0 space-y-1.5 bg-gradient-to-t from-black/90 via-black/50 to-transparent p-2.5 pt-8">
                      <div className="h-0.5 overflow-hidden rounded-full bg-white/25">
                        <div
                          className="h-full rounded-full bg-white transition-[width]"
                          style={{ width: `${Math.min(100, tvProgress * 100)}%` }}
                        />
                      </div>
                      <div className="flex items-center gap-2">
                        <button
                          onClick={toggleTv}
                          className="flex h-7 w-7 items-center justify-center rounded-full bg-white/15 text-white hover:bg-white/25"
                          aria-label={tvPlaying ? "Pause Joe TV" : "Play Joe TV"}
                        >
                          {tvPlaying ? (
                            <PauseIcon className="h-3.5 w-3.5" />
                          ) : (
                            <PlayIcon className="h-3.5 w-3.5 ml-0.5" />
                          )}
                        </button>
                        <span className="text-[0.55rem] font-semibold uppercase tracking-wider text-white/75">
                          Joe TV preview
                        </span>
                        <button
                          onClick={renderMp4}
                          disabled={mp4Busy}
                          className="ml-auto rounded-full bg-white/15 px-2 py-1 text-[0.53rem] font-semibold uppercase tracking-wider text-white hover:bg-white/25 disabled:opacity-60"
                        >
                          {mp4Busy ? "Rendering…" : "MP4"}
                        </button>
                      </div>
                      {tvError && (
                        <p className="text-[0.55rem] leading-snug text-red-300">
                          {tvError}{" "}
                          <a
                            href={video.pageUrl}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="underline"
                          >
                            Full page ↗
                          </a>
                        </p>
                      )}
                    </div>
                  </div>
                ) : (
                  <div className="absolute inset-0">
                    <img
                      src={video.posterUrl || frames[0]}
                      alt={`${track?.episodeTitle ?? "Joe"} video`}
                      className="absolute inset-0 h-full w-full object-contain"
                    />
                    <button
                      onClick={startTv}
                      className="absolute inset-0 flex items-center justify-center bg-black/25 group"
                      aria-label="Play Joe's video in the phone"
                    >
                      <span className="flex h-14 w-14 items-center justify-center rounded-full border-2 border-white/60 bg-black/40 backdrop-blur-md transition-transform group-hover:scale-105">
                        <PlayIcon className="h-6 w-6 text-white ml-0.5" />
                      </span>
                    </button>
                    <a
                      href={video.pageUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="absolute right-2 top-2 z-30 rounded-full bg-black/60 px-2 py-0.5 text-[0.5rem] font-semibold uppercase tracking-wider text-white/85 backdrop-blur-sm hover:bg-black/80"
                    >
                      Full page ↗
                    </a>
                  </div>
                )}
                <div className="pointer-events-none absolute left-2 top-2 flex items-center gap-1 rounded-full bg-black/60 px-2 py-0.5 backdrop-blur-sm">
                  <span className="text-[0.5rem] font-bold uppercase tracking-[0.18em] text-white/90">
                    Joe TV
                  </span>
                </div>
              </div>
            )}

            {hasVideo && (
              <button
                onClick={() => {
                  if (tvOpen) {
                    previewAudioRef.current?.pause();
                    setTvOpen(false);
                    setTvPlaying(false);
                  }
                  setDismissedFor((cur) =>
                    cur === videoEpisodeId ? null : videoEpisodeId
                  );
                }}
                className="absolute bottom-2 right-2 z-30 flex h-7 w-7 items-center justify-center rounded-full bg-black/60 text-white/90 backdrop-blur-sm hover:bg-black/80"
                aria-label={showVideo ? "Show song view" : "Show Joe's video"}
              >
                {showVideo ? (
                  <span className="text-[0.7rem]">♪</span>
                ) : (
                  <PlayIcon className="h-3 w-3 ml-0.5" />
                )}
              </button>
            )}
          </div>

          {/* === PROGRESS BAR === */}
          <div className="px-3 pb-1">
            <div
              className="relative h-1 rounded-full bg-white/15 cursor-pointer"
              onClick={(e) => {
                if (!track || !track.audioUrl) return;
                const rect = e.currentTarget.getBoundingClientRect();
                const ratio = (e.clientX - rect.left) / rect.width;
                seek(ratio * durSec);
              }}
            >
              <div
                className="absolute inset-y-0 left-0 rounded-full"
                style={{
                  width: `${progressPct}%`,
                  background: "linear-gradient(90deg, oklch(0.98 0.02 80), oklch(0.95 0.05 70))",
                }}
              />
              <div
                className="absolute top-1/2 -translate-y-1/2 h-2.5 w-2.5 rounded-full bg-white shadow-md transition-[left]"
                style={{ left: `calc(${progressPct}% - 5px)` }}
              />
            </div>
          </div>

          {/* === TRANSPORT CONTROLS === */}
          <div className="flex items-center justify-center gap-4 py-2 px-3">
            <button
              onClick={restart}
              disabled={!track}
              className="text-white/80 hover:text-white disabled:opacity-30 transition-colors"
              aria-label="Restart"
            >
              <PrevIcon className="h-4 w-4" />
            </button>
            <button
              onClick={toggle}
              disabled={!track}
              className="flex items-center justify-center h-11 w-11 rounded-full bg-white text-black shadow-lg disabled:opacity-30 hover:scale-105 transition-transform"
              aria-label={isPlaying ? "Pause" : "Play"}
            >
              {audioLoading ? (
                <div className="h-5 w-5 rounded-full border-2 border-black/40 border-t-black animate-spin" />
              ) : isPlaying ? (
                <PauseIcon className="h-5 w-5" />
              ) : (
                <PlayIcon className="h-5 w-5 ml-0.5" />
              )}
            </button>
            <button
              onClick={() => seek(positionSec + 5)}
              disabled={!track || !track.audioUrl}
              className="text-white/80 hover:text-white disabled:opacity-30 transition-colors"
              aria-label="Skip 5 seconds"
            >
              <NextIcon className="h-4 w-4" />
            </button>
          </div>

          {/* === FREE COURSE CTA === */}
          {courseUrl && (
            <a
              href={courseUrl}
              target="_blank"
              rel="noopener noreferrer"
              className="mx-3 mb-1 flex items-center justify-center gap-1 rounded-md bg-white/10 px-2 py-1 text-[0.58rem] font-semibold uppercase tracking-wider text-white/85 hover:bg-white/20 transition-colors"
            >
              🎓 Free AI course — start Joe’s bootcamp
            </a>
          )}

          {/* === HOME INDICATOR === */}
          <div className="flex justify-center pb-2">
            <div className="h-1 w-24 rounded-full bg-white/40" />
          </div>
        </div>

        {/* Side buttons */}
        <div
          className="absolute -left-[3px] top-32 h-12 w-[3px] rounded-l-sm"
          style={{ background: "linear-gradient(180deg, oklch(0.7 0.02 60), oklch(0.4 0.02 50))" }}
        />
        <div
          className="absolute -left-[3px] top-48 h-16 w-[3px] rounded-l-sm"
          style={{ background: "linear-gradient(180deg, oklch(0.7 0.02 60), oklch(0.4 0.02 50))" }}
        />
        <div
          className="absolute -right-[3px] top-40 h-20 w-[3px] rounded-r-sm"
          style={{ background: "linear-gradient(180deg, oklch(0.7 0.02 60), oklch(0.4 0.02 50))" }}
        />
      </div>

      {/* === PLAY ENTIRE CLIP TOGGLE === */}
      <div
        className="w-full max-w-[280px] rounded-lg border border-border/60 bg-card p-3"
        data-active-wall={activeWallId}
      >
        <div className="flex items-center justify-between gap-2">
          <div className="flex-1 min-w-0">
            <p className="text-xs font-semibold text-foreground">
              Play Entire Clip
            </p>
            <p className="text-[0.7rem] text-muted-foreground leading-tight">
              {playEntire
                ? `Full song (~${track ? durationToSeconds(track.episodeDuration) : 60}s) — Joe's lyrics`
                : `Preview mode — first 12 seconds only`}
            </p>
          </div>
          <button
            role="switch"
            aria-checked={playEntire}
            onClick={() => setPlayEntire(!playEntire)}
            className={cn(
              "relative inline-flex h-6 w-11 shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors",
              playEntire ? "bg-primary" : "bg-muted"
            )}
          >
            <span
              className={cn(
                "inline-block h-5 w-5 transform rounded-full bg-white shadow-lg transition-transform",
                playEntire ? "translate-x-5" : "translate-x-0"
              )}
            />
          </button>
        </div>
        {/* Volume slider */}
        {track && (
          <div className="mt-3 flex items-center gap-2">
            <span className="text-[0.7rem] text-muted-foreground uppercase tracking-wider">
              Vol
            </span>
            <input
              type="range"
              min={0}
              max={100}
              value={volume}
              onChange={(e) => setVolume(parseInt(e.target.value, 10))}
              className="flex-1 h-1 rounded-full accent-primary"
            />
            <span className="text-[0.65rem] font-mono text-muted-foreground w-7 text-right">
              {volume}
            </span>
          </div>
        )}
      </div>
    </div>
  );
}

// ----------------------------------------------------------------------------
// Visualizer (animated bars over brand gradient)
// ----------------------------------------------------------------------------

function Visualizer({
  isPlaying,
  brandColor,
}: {
  isPlaying: boolean;
  brandColor: string;
}) {
  const bars = useMemo(
    () =>
      Array.from({ length: 24 }, (_, i) => ({
        base: 0.2 + ((i * 13) % 7) / 10,
        delay: (i % 6) * 0.12,
        duration: 0.7 + ((i * 7) % 5) * 0.08,
      })),
    []
  );

  return (
    <div className="absolute inset-0 overflow-hidden">
      <div
        className="absolute inset-0"
        style={{
          background: `linear-gradient(160deg, ${brandColor} 0%, ${shade(brandColor, -25)} 60%, ${shade(brandColor, -45)} 100%)`,
        }}
      />
      <div
        className="absolute inset-0 opacity-40 mix-blend-overlay"
        style={{
          background:
            "radial-gradient(circle at 30% 30%, oklch(0.99 0.02 80 / 0.7) 0%, transparent 35%), radial-gradient(circle at 70% 70%, oklch(0.98 0.04 70 / 0.5) 0%, transparent 40%)",
          animation: isPlaying ? "drift 8s ease-in-out infinite alternate" : "none",
        }}
      />
      <div className="absolute inset-x-0 bottom-0 h-1/3 flex items-end justify-center gap-[3px] px-4 pb-2 opacity-50">
        {bars.map((b, i) => (
          <div
            key={i}
            className="flex-1 max-w-[6px] rounded-t-sm bg-white/70"
            style={{
              height: isPlaying ? `${b.base * 100}%` : "10%",
              animation: isPlaying
                ? `eq ${b.duration}s ease-in-out ${b.delay}s infinite alternate`
                : "none",
            }}
          />
        ))}
      </div>
      <style jsx global>{`
        @keyframes eq {
          0% { transform: scaleY(0.4); }
          100% { transform: scaleY(1.2); }
        }
        @keyframes drift {
          0% { transform: translate(-4%, -2%) scale(1); }
          100% { transform: translate(4%, 2%) scale(1.05); }
        }
        @keyframes fadein {
          from { opacity: 0; transform: translateY(4px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
}

